create table RB_APPR_LETTER (APPR_LETTER_NO VARCHAR(50) not null  ,TRAN_BRANCH VARCHAR(30) null  ,CLIENT_NO VARCHAR(22) not null  ,OPEN_DATE TIMESTAMP(3) null  ,MATURITY_DATE TIMESTAMP(3) null  ,APPR_TYPE VARCHAR(2) null  ,FUND_PURPOSE VARCHAR(50) null  ,FUND_SOURCE VARCHAR(1) null  ,CAPITAL_AMT DECIMAL(17,2) null  ,APPR_ACCT_IND VARCHAR(2) null  ,ACCT_TYPE VARCHAR(1) null  ,EXPEND_SCOPE VARCHAR(200) null  ,INCOME_SCOPE VARCHAR(50) null  ,NARRATIVE VARCHAR(600) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,USER_ID VARCHAR(30) null  ,COMPANY VARCHAR(20) null  ,REMARK VARCHAR(200) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(APPR_LETTER_NO,CLIENT_NO));